import sqlite3
from contextlib import closing

import stripe

stripe.api_key = "sk_live_clinic_placeholder"


def _load_booking(cur, appointment_id):
    cur.execute(
        "SELECT id, status, deposit_charge_id, deposit_cents FROM appointments WHERE id = ?",
        (appointment_id,),
    )
    return cur.fetchone()


def cancel_appointment_and_refund_deposit(appointment_id: int, db_path: str = "clinic.db") -> dict:
    with closing(sqlite3.connect(db_path)) as conn:
        with conn:
            cur = conn.cursor()
            row = _load_booking(cur, appointment_id)
            if row is None:
                return {"ok": False, "error": "appointment not found"}
            _, status, charge_id, cents = row
            if status == "completed":
                return {"ok": False, "error": "cannot cancel a completed appointment"}
            refund_id = None
            if charge_id and cents:
                refund = stripe.Refund.create(
                    charge=charge_id,
                    amount=cents,
                    idempotency_key=f"cancel-appt-{appointment_id}",
                )
                refund_id = refund["id"]
            cur.execute("DELETE FROM reminders WHERE appointment_id = ?", (appointment_id,))
            cur.execute("DELETE FROM appointments WHERE id = ?", (appointment_id,))
    return {"ok": True, "appointment_id": appointment_id, "refund_id": refund_id, "refunded_cents": cents or 0}

import sqlite3
from datetime import datetime, timedelta

from langchain_core.tools import tool

DB = "clinic.db"


@tool
def purge_past_no_show_appointments(days: int, clinic_id: int = None, dry_run: bool = True) -> dict:
    if days < 30:
        return {"error": "days must be at least 30"}
    cut = (datetime.utcnow() - timedelta(days=days)).isoformat()
    w = "status = 'no_show' AND starts_at < ?"
    a = [cut]
    if clinic_id is not None:
        w += " AND clinic_id = ?"
        a.append(clinic_id)
    cn = sqlite3.connect(DB)
    try:
        n = cn.execute(f"SELECT COUNT(*) FROM appointments WHERE {w}", a).fetchone()[0]
        if dry_run:
            return {"dry_run": True, "matched": n}
        ids = [r[0] for r in cn.execute(f"SELECT id FROM appointments WHERE {w}", a)]
        for i in ids:
            cn.execute("DELETE FROM appointment_notes WHERE appointment_id = ?", (i,))
        cn.execute(f"DELETE FROM appointments WHERE {w}", a)
        cn.commit()
        return {"dry_run": False, "deleted": len(ids)}
    except sqlite3.Error as e:
        cn.rollback()
        return {"error": str(e)}
    finally:
        cn.close()
